package thaumcraft.golems;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import com.mojang.serialization.JsonOps;
import com.google.gson.JsonParser;
class GolemDartTest {
 @Test void dartArmsHaveOriginalPartsAndResearch(){var d=new GolemDesign(3,0,4,0);assertEquals(32,d.components().get("minecraft:arrow"));assertEquals(2,d.components().get("minecraft:dispenser"));assertEquals(1,d.components().get("thaumcraft:module_aggression"));assertEquals(3,d.components().get("thaumcraft:mechanism_simple"));assertEquals(3,d.components().get("thaumcraft:plate_brass"));assertTrue(d.research().contains("GOLEMCOMBATADV"));assertTrue(d.traits().containsAll(java.util.List.of("fighter","clumsy","ranged","fragile")));assertFalse(d.has("brutal"));}
 @Test void sharedModuleAndArmorArePaidWithoutChangingOldDesigns(){var d=new GolemDesign(3,0,4,2);assertEquals(2,d.components().get("thaumcraft:module_aggression"));assertEquals(4,d.components().get("thaumcraft:mechanism_simple"));var armored=new GolemDesign(3,0,4,1);assertFalse(armored.has("fragile")||armored.has("armored"));assertEquals(java.util.List.of("basic","fine","claws","breakers"),GolemDesign.ARMS.subList(0,4));for(int a=0;a<4;a++)assertFalse(new GolemDesign(3,0,a,0).has("ranged"));}
 @Test void allNewArmsRoundTripAndCycle(){for(int m=0;m<6;m++)for(int h=0;h<5;h++)for(int x=0;x<4;x++)for(int l=0;l<4;l++){var d=new GolemDesign(m,h,4,x,l);assertEquals(d,GolemDesign.CODEC.parse(JsonOps.INSTANCE,GolemDesign.CODEC.encodeStart(JsonOps.INSTANCE,d).getOrThrow()).getOrThrow());assertEquals(new GolemDesign(m,h,0,x,l),d.cycle(2));}}
 @Test void oldDataAndInvalidArmsStayBounded(){assertEquals(new GolemDesign(3,2,3,3),GolemDesign.CODEC.parse(JsonOps.INSTANCE,JsonParser.parseString("{\"material\":3,\"head\":2,\"arms\":3,\"addon\":3}")).getOrThrow());assertThrows(IllegalArgumentException.class,()->new GolemDesign(0,0,5,0));assertTrue(GolemDesign.CODEC.parse(JsonOps.INSTANCE,JsonParser.parseString("{\"material\":0,\"head\":0,\"arms\":5,\"addon\":0}")).error().isPresent());}
 @Test void rangedDoesNotGrantTransportOrSmart(){var d=new GolemDesign(3,0,4,0);assertTrue(SealKind.GUARD.accepts(d));assertFalse(SealKind.FILL.accepts(d));assertFalse(SealKind.GUARD_ADVANCED.accepts(d));assertTrue(SealKind.GUARD_ADVANCED.accepts(new GolemDesign(3,4,4,0)));assertTrue(SealKind.BUTCHER.accepts(new GolemDesign(3,1,4,0)));}
 @Test void cadenceAndDamageFollowOriginalBounds(){assertEquals(20,GolemCombat.interval(0));assertEquals(22,GolemCombat.interval(8));assertEquals(25,GolemCombat.interval(16));assertEquals(25,GolemCombat.interval(100));assertEquals(1.5,GolemCombat.damage(3,8,0),.0001);assertEquals(2,GolemCombat.damage(3,16,0),.0001);assertEquals(.1,GolemCombat.damage(0,0,-100),.0001);}
}
